import numpy as np
from scipy.spatial.distance import cdist
from itertools import permutations

def kissing_number11() -> np.ndarray:
    """
    Constructs a collection of 11-dimensional points with integral coordinates such that their maximum norm is smaller than their minimum pairwise distance, aiming to maximize the number of points.

    Returns:
        points: np.ndarray of shape (num_points, 11)
    """
    d = 11  # Dimension
    max_norm = 10  # Set a reasonable maximum norm for candidate points

    # Step 1: Generate points from a lattice shell of Λ_11
    def generate_lattice_shell(radius: int):
        """Generate lattice shell with L2 norm approximately equal to radius."""
        candidates = []
        for i in range(-radius, radius + 1):
            for j in range(-radius, radius + 1):
                for k in range(-radius, radius + 1):
                    for l in range(-radius, radius + 1):
                        for m in range(-radius, radius + 1):
                            for n in range(-radius, radius + 1):
                                for o in range(-radius, radius + 1):
                                    for p in range(-radius, radius + 1):
                                        for q in range(-radius, radius + 1):
                                            for r in range(-radius, radius + 1):
                                                for s in range(-radius, radius + 1):
                                                    point = np.array([i, j, k, l, m, n, o, p, q, r, s])
                                                    if np.isclose(np.linalg.norm(point), radius, atol=0.5):
                                                        candidates.append(point)
        return np.array(candidates)

    # Generate candidates from lattice shells within a specific radius range
    candidate_points = []
    for radius in range(1, max_norm + 1):
        candidate_points.extend(generate_lattice_shell(radius))
    candidate_points = np.array(candidate_points)

    # Step 2: Apply greedy filtering to maximize valid points
    valid_points = []
    for candidate in candidate_points:
        if len(valid_points) == 0:
            valid_points.append(candidate)
        else:
            pairwise_distances = cdist([candidate], valid_points)
            if np.all(pairwise_distances > np.linalg.norm(candidate)):
                valid_points.append(candidate)
    valid_points = np.array(valid_points)

    # Step 3: Apply symmetry transformations to increase diversity
    def apply_symmetry(points):
        """Generate symmetric permutations and reflections of points."""
        symmetric_points = set()
        for point in points:
            # Generate all permutations of the coordinates
            for perm in permutations(point):
                symmetric_points.add(tuple(perm))
            # Add reflections (negating each coordinate)
            symmetric_points.add(tuple(-1 * np.array(point)))
        return np.array([np.array(p) for p in symmetric_points])

    valid_points = apply_symmetry(valid_points)

    return valid_points

